// Byte-accurate packet builder. Every simulated packet in NETLAB is produced here:
// real header layouts, real field encodings and correctly computed checksums.
// Packets are SIMULATED (generated by this code), never captured from a live network.
import {
  u16, u24, u32, ascii, parseMac, fmtMac, parseIPv4, parseIPv6, fmtIPv6, inetChecksum, hex2, hex4, prngBytes,
} from './bytes';

export interface Field {
  name: string;
  start: number; // absolute byte offset
  len: number;
  value: string;
  explain: string;
  bits?: string; // for bit-packed fields, a breakdown
}
export interface Layer {
  id: string;
  name: string;
  osi: number;
  start: number;
  len: number;
  fields: Field[];
  simple: string;
}
export interface Packet {
  bytes: number[];
  layers: Layer[];
  meta: Record<string, string>;
  summary: string;
}

interface Enc { bytes: number[]; layers: Layer[]; meta: Record<string, string>; summary: string }

class W {
  b: number[] = [];
  f: Field[] = [];
  put(name: string, bytes: number[], value: string, explain: string, bits?: string) {
    this.f.push({ name, start: this.b.length, len: bytes.length, value, explain, bits });
    this.b.push(...bytes);
    return this.f.length - 1;
  }
  patch(idx: number, bytes: number[], value: string) {
    const fld = this.f[idx];
    bytes.forEach((v, i) => (this.b[fld.start + i] = v));
    fld.value = value;
  }
}

function wrap(w: W, layer: Omit<Layer, 'start' | 'len' | 'fields'>, inner: Enc | null, meta: Record<string, string>, summary?: string): Enc {
  const own = w.b.length;
  const innerBytes = inner?.bytes ?? [];
  const shifted = (inner?.layers ?? []).map((l) => ({
    ...l,
    start: l.start + own,
    fields: l.fields.map((f) => ({ ...f, start: f.start + own })),
  }));
  return {
    bytes: [...w.b, ...innerBytes],
    layers: [{ ...layer, start: 0, len: own, fields: w.f }, ...shifted],
    meta: { ...(inner?.meta ?? {}), ...meta },
    summary: summary ?? inner?.summary ?? '',
  };
}

// ---------------------------------------------------------------- Specs
export interface EthSpec { src: string; dst: string; vlan?: number[]; type?: number }
export interface IPv4Spec { src: string; dst: string; ttl?: number; id?: number; df?: boolean; dscp?: number }
export interface IPv6Spec { src: string; dst: string; hop?: number; flow?: number }
export interface TcpSpec { sport: number; dport: number; seq: number; ack?: number; flags: string; win?: number; mss?: number }
export interface UdpSpec { sport: number; dport: number }
export interface IcmpSpec { type: number; code: number; id?: number; seq?: number; data?: string; inner?: number[] }
export interface Icmp6Spec { type: number; code: number; id?: number; seq?: number; data?: string; target?: string; mac?: string }
export interface ArpSpec { op: 1 | 2; sha: string; spa: string; tha: string; tpa: string }
export interface DnsRR { name: string; type: string; ttl: number; data: string; pref?: number }
export interface DnsSpec { id: number; response: boolean; rd?: boolean; ra?: boolean; aa?: boolean; rcode?: number; qname: string; qtype: string; answers?: DnsRR[] }
export interface DhcpSpec {
  op: 1 | 2; msg: 'DISCOVER' | 'OFFER' | 'REQUEST' | 'ACK' | 'NAK' | 'RELEASE'; xid: number; chaddr: string;
  ciaddr?: string; yiaddr?: string; siaddr?: string; broadcast?: boolean;
  requested?: string; server?: string; lease?: number; mask?: string; router?: string; dns?: string[]; hostname?: string;
}
export interface TlsRecord {
  kind: 'ClientHello' | 'ServerHello' | 'ChangeCipherSpec' | 'Encrypted' | 'Alert';
  sni?: string; seed?: number; len?: number; note?: string;
}
export type AppSpec =
  | { kind: 'dns'; dns: DnsSpec }
  | { kind: 'dhcp'; dhcp: DhcpSpec }
  | { kind: 'http'; text: string }
  | { kind: 'tls'; records: TlsRecord[] }
  | { kind: 'raw'; text: string; name?: string };

export interface PacketSpec {
  eth?: EthSpec;
  arp?: ArpSpec;
  ipv4?: IPv4Spec;
  ipv6?: IPv6Spec;
  tcp?: TcpSpec;
  udp?: UdpSpec;
  icmp?: IcmpSpec;
  icmp6?: Icmp6Spec;
  app?: AppSpec;
}

// ---------------------------------------------------------------- Application layer
const DNS_TYPES: Record<string, number> = { A: 1, NS: 2, CNAME: 5, SOA: 6, PTR: 12, MX: 15, TXT: 16, AAAA: 28, ANY: 255 };
function dnsName(name: string): number[] {
  const out: number[] = [];
  for (const label of name.replace(/\.$/, '').split('.')) {
    if (!label) continue;
    const b = ascii(label);
    out.push(b.length, ...b);
  }
  out.push(0);
  return out;
}

function encDns(d: DnsSpec): Enc {
  const w = new W();
  w.put('Transaction ID', u16(d.id), hex4(d.id), 'Random 16-bit identifier chosen by the client. The response must echo it so the resolver can match answers to questions (and so off-path attackers must guess it).');
  const flags = (d.response ? 0x8000 : 0) | (d.aa ? 0x0400 : 0) | (d.rd !== false ? 0x0100 : 0) | (d.ra ? 0x0080 : 0) | (d.rcode ?? 0);
  w.put('Flags', u16(flags), hex4(flags), 'QR (query/response), Opcode, AA (authoritative answer), TC (truncated), RD (recursion desired), RA (recursion available) and RCODE (0 = NOERROR, 3 = NXDOMAIN).',
    `QR=${d.response ? 1 : 0} Opcode=0 AA=${d.aa ? 1 : 0} TC=0 RD=${d.rd !== false ? 1 : 0} RA=${d.ra ? 1 : 0} RCODE=${d.rcode ?? 0}`);
  const an = d.answers ?? [];
  w.put('Questions', u16(1), '1', 'Number of entries in the Question section.');
  w.put('Answer RRs', u16(an.length), String(an.length), 'Number of resource records in the Answer section.');
  w.put('Authority RRs', u16(0), '0', 'Number of name-server records in the Authority section.');
  w.put('Additional RRs', u16(0), '0', 'Number of records in the Additional section (EDNS0 OPT records live here in modern traffic).');
  w.put('Query name', dnsName(d.qname), d.qname, 'Domain name encoded as length-prefixed labels terminated by a zero byte, e.g. 3"www"7"example"3"com"0.');
  w.put('Query type', u16(DNS_TYPES[d.qtype] ?? 1), `${d.qtype} (${DNS_TYPES[d.qtype]})`, 'The record type being requested: A=1, NS=2, CNAME=5, PTR=12, MX=15, TXT=16, AAAA=28.');
  w.put('Query class', u16(1), 'IN (1)', 'Class IN = Internet. Practically always 1.');
  an.forEach((rr, i) => {
    const sameAsQ = rr.name.replace(/\.$/, '') === d.qname.replace(/\.$/, '');
    w.put(`Answer ${i + 1}: name`, sameAsQ ? [0xc0, 0x0c] : dnsName(rr.name), sameAsQ ? `${rr.name} (pointer 0xc00c)` : rr.name,
      sameAsQ ? 'Message compression: 0xC0 marks a pointer, 0x0C (12) is the offset of the question name inside the DNS message, so the name is not repeated.' : 'Owner name of this record.');
    w.put(`Answer ${i + 1}: type`, u16(DNS_TYPES[rr.type]), rr.type, 'Record type of this answer.');
    w.put(`Answer ${i + 1}: class`, u16(1), 'IN', 'Internet class.');
    w.put(`Answer ${i + 1}: TTL`, u32(rr.ttl), `${rr.ttl} s`, 'How long resolvers may cache this record, in seconds.');
    let rdata: number[];
    if (rr.type === 'A') rdata = parseIPv4(rr.data);
    else if (rr.type === 'AAAA') rdata = parseIPv6(rr.data);
    else if (rr.type === 'MX') rdata = [...u16(rr.pref ?? 10), ...dnsName(rr.data)];
    else if (rr.type === 'TXT') { const t = ascii(rr.data); rdata = [t.length, ...t]; }
    else rdata = dnsName(rr.data);
    w.put(`Answer ${i + 1}: data length`, u16(rdata.length), String(rdata.length), 'Length of the RDATA that follows.');
    w.put(`Answer ${i + 1}: ${rr.type} data`, rdata, rr.type === 'MX' ? `pref ${rr.pref ?? 10}, ${rr.data}` : rr.data, rdataExplain(rr.type));
  });
  const summary = d.response
    ? `DNS standard query response ${hex4(d.id)} ${d.qtype} ${d.qname}${an.map((a) => ` ${a.type} ${a.data}`).join('')}`
    : `DNS standard query ${hex4(d.id)} ${d.qtype} ${d.qname}`;
  return wrap(w, { id: 'dns', name: 'Domain Name System', osi: 7, simple: d.response
    ? `The DNS server answers: "${d.qname}" ${an.length ? 'is at ' + an.map((a) => a.data).join(', ') : 'has no such record'}. The ID matches the question so the client knows this is its answer.`
    : `The client asks a DNS server: "What is the ${d.qtype} record for ${d.qname}?" — like looking a name up in a phone book.` }, null,
  { protocol: 'DNS', payload: summary }, summary);
}
function rdataExplain(t: string) {
  return ({
    A: 'A 32-bit IPv4 address.',
    AAAA: 'A 128-bit IPv6 address.',
    CNAME: 'Canonical name: this name is an alias for another name.',
    MX: 'Mail exchanger: a 16-bit preference (lower is preferred) followed by a mail server name.',
    NS: 'Name of an authoritative name server for the zone.',
    TXT: 'Free-form text, used for SPF, DKIM, domain verification and similar.',
    PTR: 'Pointer: the name associated with an address (reverse DNS).',
  } as Record<string, string>)[t] ?? 'Record data.';
}

const DHCP_MSG: Record<string, number> = { DISCOVER: 1, OFFER: 2, REQUEST: 3, NAK: 6, ACK: 5, RELEASE: 7 };
function encDhcp(d: DhcpSpec): Enc {
  const w = new W();
  const z = '0.0.0.0';
  w.put('Message type (op)', [d.op], d.op === 1 ? 'Boot Request (1)' : 'Boot Reply (2)', 'BOOTP op code: 1 = request from client, 2 = reply from server. DHCP is built on top of the older BOOTP format.');
  w.put('Hardware type', [1], 'Ethernet (1)', 'Type of the client hardware address.');
  w.put('Hardware address length', [6], '6', 'MAC addresses are 6 bytes long.');
  w.put('Hops', [0], '0', 'Incremented by DHCP relay agents.');
  w.put('Transaction ID', u32(d.xid), '0x' + d.xid.toString(16).padStart(8, '0'), 'Random number chosen by the client and repeated in every message of the same exchange.');
  w.put('Seconds elapsed', u16(0), '0', 'Seconds since the client began acquiring an address.');
  const fl = d.broadcast ? 0x8000 : 0;
  w.put('Flags', u16(fl), d.broadcast ? '0x8000 (Broadcast)' : '0x0000 (Unicast)', 'The broadcast bit asks the server to broadcast its reply because the client cannot yet receive unicast IP.');
  w.put('Client IP (ciaddr)', parseIPv4(d.ciaddr ?? z), d.ciaddr ?? z, 'Filled in only when the client already has a usable address (renewals).');
  w.put('Your IP (yiaddr)', parseIPv4(d.yiaddr ?? z), d.yiaddr ?? z, 'The address the server is offering/assigning to the client.');
  w.put('Next server IP (siaddr)', parseIPv4(d.siaddr ?? z), d.siaddr ?? z, 'Server to use in the next bootstrap step (e.g. TFTP for network boot).');
  w.put('Relay agent IP (giaddr)', parseIPv4(z), z, 'Set by a relay agent when the server is on another subnet.');
  w.put('Client MAC (chaddr)', [...parseMac(d.chaddr), ...Array(10).fill(0)], d.chaddr, 'The client hardware address, padded to 16 bytes. Servers use it to identify the client.');
  w.put('Server host name', Array(64).fill(0), '(not given)', '64-byte legacy BOOTP field, usually empty.');
  w.put('Boot file name', Array(128).fill(0), '(not given)', '128-byte legacy BOOTP field, usually empty.');
  w.put('Magic cookie', [0x63, 0x82, 0x53, 0x63], 'DHCP (63 82 53 63)', 'Marks the start of DHCP options; distinguishes DHCP from plain BOOTP.');
  w.put('Option 53: DHCP Message Type', [53, 1, DHCP_MSG[d.msg]], `${d.msg} (${DHCP_MSG[d.msg]})`, 'Says which DHCP message this is: 1 Discover, 2 Offer, 3 Request, 5 ACK, 6 NAK, 7 Release.');
  if (d.requested) w.put('Option 50: Requested IP', [50, 4, ...parseIPv4(d.requested)], d.requested, 'The address the client wants (from the Offer).');
  if (d.server) w.put('Option 54: Server Identifier', [54, 4, ...parseIPv4(d.server)], d.server, 'Identifies which DHCP server the client chose — other servers withdraw their offers.');
  if (d.lease) w.put('Option 51: Lease Time', [51, 4, ...u32(d.lease)], `${d.lease} s (${(d.lease / 3600).toFixed(0)} h)`, 'How long the client may use the address before renewing (renewal starts at 50%, T1).');
  if (d.mask) w.put('Option 1: Subnet Mask', [1, 4, ...parseIPv4(d.mask)], d.mask, 'Subnet mask for the client\'s network.');
  if (d.router) w.put('Option 3: Router', [3, 4, ...parseIPv4(d.router)], d.router, 'Default gateway the client should use for off-subnet traffic.');
  if (d.dns) w.put('Option 6: DNS Servers', [6, d.dns.length * 4, ...d.dns.flatMap(parseIPv4)], d.dns.join(', '), 'Recursive DNS resolvers for the client.');
  if (d.hostname) { const h = ascii(d.hostname); w.put('Option 12: Host Name', [12, h.length, ...h], d.hostname, 'Client host name.'); }
  if (d.op === 1 && d.msg !== 'RELEASE') w.put('Option 55: Parameter Request List', [55, 4, 1, 3, 6, 15], 'Mask, Router, DNS, Domain', 'The options the client would like the server to include.');
  w.put('Option 255: End', [255], 'End', 'Marks the end of the options list.');
  const summary = `DHCP ${d.msg} - Transaction ID 0x${d.xid.toString(16)}`;
  const simple: Record<string, string> = {
    DISCOVER: 'A brand-new device shouts to the whole network: "Is there a DHCP server? I need an IP address!" It has no address yet, so it uses 0.0.0.0 as source and broadcasts.',
    OFFER: `The DHCP server replies: "You can use ${d.yiaddr}." It also suggests a subnet mask, gateway, DNS server and lease time.`,
    REQUEST: `The client broadcasts: "I accept ${d.requested} from server ${d.server}." Broadcasting tells any other servers their offers were declined.`,
    ACK: `The server confirms: "${d.yiaddr} is yours for ${((d.lease ?? 0) / 3600).toFixed(0)} hours." The client can now configure its interface.`,
    NAK: 'The server refuses the request; the client must start over with a Discover.',
    RELEASE: 'The client hands its address back to the server.',
  };
  return wrap(w, { id: 'dhcp', name: 'Dynamic Host Configuration Protocol', osi: 7, simple: simple[d.msg] }, null, { protocol: 'DHCP', payload: summary }, summary);
}

function encHttp(text: string): Enc {
  const w = new W();
  const lines = text.replace(/\r?\n/g, '\r\n').split('\r\n');
  const bodyIdx = lines.indexOf('');
  const head = bodyIdx >= 0 ? lines.slice(0, bodyIdx) : lines;
  head.forEach((ln, i) => {
    const b = ascii(ln + '\r\n');
    if (i === 0) {
      const isResp = ln.startsWith('HTTP/');
      w.put(isResp ? 'Status line' : 'Request line', b, ln, isResp
        ? 'Protocol version, numeric status code (2xx success, 3xx redirect, 4xx client error, 5xx server error) and reason phrase.'
        : 'Method (GET, POST, …), request target (path) and protocol version.');
    } else {
      const name = ln.split(':')[0];
      w.put(`Header: ${name}`, b, ln.slice(name.length + 1).trim(), headerExplain(name));
    }
  });
  if (bodyIdx >= 0) {
    w.put('End of headers', [13, 10], '\\r\\n', 'An empty line (CRLF) separates headers from the body.');
    const body = lines.slice(bodyIdx + 1).join('\r\n');
    if (body) w.put('Body', ascii(body), body.length > 40 ? body.slice(0, 40) + '…' : body, 'The message body — here, the HTML document.');
  }
  const first = head[0];
  const resp = first.startsWith('HTTP/');
  return wrap(w, { id: 'http', name: 'Hypertext Transfer Protocol', osi: 7, simple: resp
    ? `The web server answers "${first.split(' ').slice(1).join(' ')}" and sends back the page content with headers describing it.`
    : `The browser asks the web server: "${first.split(' ')[0]} me ${first.split(' ')[1]} please." Headers add details like which site (Host) and what formats it accepts.` },
  null, { protocol: 'HTTP', payload: first }, first);
}
function headerExplain(h: string): string {
  return ({
    Host: 'Which website is wanted — lets one IP address host many sites (virtual hosting). Mandatory in HTTP/1.1.',
    'User-Agent': 'Identifies the client software.',
    Accept: 'Media types the client can handle.',
    'Accept-Encoding': 'Compression schemes the client supports (gzip, br).',
    Connection: 'Whether to keep the TCP connection open for more requests.',
    'Content-Type': 'Media type of the body.',
    'Content-Length': 'Size of the body in bytes so the receiver knows where the message ends.',
    Server: 'Identifies the server software.',
    Date: 'When the response was generated.',
    'Cache-Control': 'Caching rules for browsers and proxies.',
    'Set-Cookie': 'Stores a cookie in the browser — often a session identifier.',
    Cookie: 'Sends stored cookies back to the server — often the session identifier.',
    Location: 'Target of a redirect.',
    Upgrade: 'Asks to switch protocols on this connection (e.g. to WebSocket).',
    'Sec-WebSocket-Key': 'Random nonce the server hashes to prove it understands WebSocket.',
    'Strict-Transport-Security': 'HSTS: tells the browser to only use HTTPS for this site in future.',
  } as Record<string, string>)[h] ?? 'HTTP header field.';
}

function encTls(records: TlsRecord[]): Enc {
  const w = new W();
  const summaries: string[] = [];
  records.forEach((r, ri) => {
    const p = records.length > 1 ? `[${ri + 1}] ` : '';
    if (r.kind === 'ClientHello' || r.kind === 'ServerHello') {
      const isC = r.kind === 'ClientHello';
      const seed = r.seed ?? (isC ? 7 : 11);
      const sni = ascii(r.sni ?? 'www.example.com');
      const exts: number[] = [];
      if (isC) {
        exts.push(...u16(0), ...u16(sni.length + 5), ...u16(sni.length + 3), 0, ...u16(sni.length), ...sni);
        exts.push(...u16(43), ...u16(5), 4, 0x03, 0x04, 0x03, 0x03); // supported_versions: TLS1.3, TLS1.2
        exts.push(...u16(10), ...u16(4), ...u16(2), ...u16(0x001d)); // supported_groups: x25519
        exts.push(...u16(13), ...u16(6), ...u16(4), ...u16(0x0403), ...u16(0x0804)); // signature_algorithms
        exts.push(...u16(51), ...u16(38), ...u16(36), ...u16(0x001d), ...u16(32), ...prngBytes(seed + 3, 32)); // key_share
      } else {
        exts.push(...u16(43), ...u16(2), 0x03, 0x04);
        exts.push(...u16(51), ...u16(36), ...u16(0x001d), ...u16(32), ...prngBytes(seed + 3, 32));
      }
      const suites = isC ? [...u16(6), ...u16(0x1301), ...u16(0x1302), ...u16(0x1303)] : u16(0x1301);
      const sid = prngBytes(seed + 1, 32);
      const body = [0x03, 0x03, ...prngBytes(seed, 32), 32, ...sid, ...suites, ...(isC ? [1, 0] : [0]), ...u16(exts.length), ...exts];
      const hs = [isC ? 1 : 2, ...u24(body.length), ...body];
      w.put(`${p}Record: content type`, [22], 'Handshake (22)', 'TLS record content type: 20 ChangeCipherSpec, 21 Alert, 22 Handshake, 23 Application Data.');
      w.put(`${p}Record: legacy version`, [0x03, 0x01 + (isC ? 0 : 2)], isC ? 'TLS 1.0 (0x0301)' : 'TLS 1.2 (0x0303)', 'Legacy record version kept for middlebox compatibility; the real version is negotiated in the supported_versions extension.');
      w.put(`${p}Record: length`, u16(hs.length), String(hs.length), 'Length of the record payload.');
      w.put(`${p}Handshake type`, [hs[0]], isC ? 'ClientHello (1)' : 'ServerHello (2)', 'Which handshake message follows.');
      w.put(`${p}Handshake length`, u24(body.length), String(body.length), '24-bit length of the handshake message body.');
      w.put(`${p}Legacy version`, [0x03, 0x03], 'TLS 1.2 (0x0303)', 'Frozen at 0x0303 in TLS 1.3 for compatibility.');
      w.put(`${p}Random`, prngBytes(seed, 32), '32 random bytes', 'Fresh randomness from each side, mixed into the key schedule so every session gets unique keys.');
      w.put(`${p}Session ID`, [32, ...sid], '32 bytes', 'Legacy session ID (TLS 1.3 uses it only for middlebox compatibility mode).');
      w.put(`${p}Cipher suite${isC ? 's' : ''}`, suites, isC ? 'TLS_AES_128_GCM_SHA256, TLS_AES_256_GCM_SHA384, TLS_CHACHA20_POLY1305_SHA256' : 'TLS_AES_128_GCM_SHA256 (0x1301)',
        isC ? 'Cipher suites the client supports, in order of preference.' : 'The single cipher suite the server picked.');
      w.put(`${p}Compression`, isC ? [1, 0] : [0], 'null', 'Compression is disabled (TLS compression enabled the CRIME attack).');
      w.put(`${p}Extensions`, [...u16(exts.length), ...exts], isC ? `server_name=${r.sni ?? 'www.example.com'}, supported_versions, supported_groups, signature_algorithms, key_share(x25519)` : 'supported_versions=TLS1.3, key_share(x25519)',
        isC ? 'SNI tells the server which site is wanted (sent in clear text!). key_share carries the client\'s ephemeral X25519 public key so keys can be derived after just one round trip.'
          : 'The server confirms TLS 1.3 and sends its own ephemeral X25519 public key. Both sides now compute the same shared secret (ECDHE) — it is never transmitted.');
      summaries.push(isC ? 'Client Hello' : 'Server Hello');
    } else if (r.kind === 'ChangeCipherSpec') {
      w.put(`${p}ChangeCipherSpec record`, [20, 0x03, 0x03, 0, 1, 1], 'Change Cipher Spec', 'In TLS 1.3 this is a dummy record sent only for middlebox compatibility.');
      summaries.push('Change Cipher Spec');
    } else if (r.kind === 'Alert') {
      w.put(`${p}Alert record`, [21, 0x03, 0x03, 0, 2, 2, 42], 'fatal: bad_certificate (42)', 'Alerts signal errors or closure. Level 2 = fatal; description 42 = bad_certificate.');
      summaries.push('Alert (bad_certificate)');
    } else {
      const len = r.len ?? 64;
      w.put(`${p}Record header`, [23, 0x03, 0x03, ...u16(len)], `Application Data, ${len} bytes`, 'Content type 23 (Application Data). In TLS 1.3 every encrypted record looks like this from the outside — the true type is hidden inside.');
      w.put(`${p}Encrypted payload`, prngBytes(r.seed ?? 99 + ri, len), r.note ?? 'ciphertext + 16-byte AEAD tag', 'AES-GCM ciphertext followed by an authentication tag. Without the session keys these bytes are indistinguishable from random noise.');
      summaries.push(r.note ? `Application Data (${r.note})` : 'Application Data');
    }
  });
  const summary = 'TLSv1.3 ' + summaries.join(', ');
  const enc = records.some((r) => r.kind === 'Encrypted');
  return wrap(w, { id: 'tls', name: 'Transport Layer Security', osi: 6, simple: enc
    ? 'This data is encrypted with session keys only the browser and server know. Anyone in the middle sees only random-looking bytes — the protected content is listed only as a label.'
    : records[0]?.kind === 'ClientHello'
      ? 'The browser says hello: "I speak TLS 1.3, here are the ciphers I support, here is my half of a key exchange, and I want www.example.com."'
      : 'The server picks a cipher and sends its half of the key exchange. Both sides can now compute the same secret key without ever sending it.' },
  null, { protocol: 'TLS', payload: summary }, summary);
}

function encRaw(text: string, name = 'Payload'): Enc {
  const w = new W();
  w.put('Data', ascii(text), text.length > 48 ? text.slice(0, 48) + '…' : text, 'Application data carried by this packet.');
  return wrap(w, { id: 'data', name, osi: 7, simple: `Application data: "${text.slice(0, 60)}"` }, null, { payload: text.slice(0, 60) }, name);
}

// ---------------------------------------------------------------- Transport
const TCP_FLAGS = ['FIN', 'SYN', 'RST', 'PSH', 'ACK', 'URG', 'ECE', 'CWR'];
function tcpFlagBits(flags: string) {
  const set = flags.toUpperCase().split(/[,\s/|+]+/).filter(Boolean);
  return TCP_FLAGS.reduce((acc, f, i) => (set.includes(f) ? acc | (1 << i) : acc), 0);
}
function pseudo(src: number[], dst: number[], proto: number, len: number) {
  return src.length === 4
    ? [...src, ...dst, 0, proto, ...u16(len)]
    : [...src, ...dst, ...u32(len), 0, 0, 0, proto];
}

function encTcp(t: TcpSpec, inner: Enc | null, src: number[], dst: number[]): Enc {
  const w = new W();
  w.put('Source port', u16(t.sport), String(t.sport), 'Port of the sending application. Clients use a random ephemeral port (49152–65535).');
  w.put('Destination port', u16(t.dport), String(t.dport), 'Port of the receiving application (e.g. 443 HTTPS, 80 HTTP, 22 SSH).');
  w.put('Sequence number', u32(t.seq >>> 0), String(t.seq >>> 0), 'Byte position of the first data byte in this segment. A SYN consumes one sequence number. The initial value (ISN) is randomised.');
  w.put('Acknowledgment number', u32((t.ack ?? 0) >>> 0), String((t.ack ?? 0) >>> 0), 'Valid when ACK is set: the next sequence number the sender expects to receive — i.e. "I have everything before this".');
  const hdrLen = t.mss ? 24 : 20;
  const fl = tcpFlagBits(t.flags);
  const flagNames = TCP_FLAGS.filter((_, i) => fl & (1 << i));
  w.put('Header length & flags', u16(((hdrLen / 4) << 12) | fl), `${hdrLen} bytes; [${flagNames.join(', ')}]`,
    'Upper 4 bits: header length in 32-bit words. Lower bits: control flags — SYN starts a connection, ACK acknowledges, FIN closes, RST aborts, PSH pushes data to the application.',
    `Data offset=${hdrLen / 4} (${hdrLen} B) | ` + TCP_FLAGS.slice().reverse().map((f) => `${f}=${fl & (1 << TCP_FLAGS.indexOf(f)) ? 1 : 0}`).join(' '));
  w.put('Window size', u16(t.win ?? 64240), String(t.win ?? 64240), 'Flow control: how many bytes the receiver is willing to accept beyond the acknowledged byte (scaled if Window Scale was negotiated).');
  const ci = w.put('Checksum', [0, 0], '', 'Covers a pseudo-header (source/destination IP, protocol, length), the TCP header and the data. Detects corruption in transit.');
  w.put('Urgent pointer', [0, 0], '0', 'Only meaningful with the URG flag — rarely used today.');
  if (t.mss) w.put('Option: MSS', [2, 4, ...u16(t.mss)], `${t.mss} bytes`, 'Maximum Segment Size: the largest payload this side can receive (1460 = 1500 MTU − 20 IP − 20 TCP). Sent only on SYN segments.');
  const seg = [...w.b, ...(inner?.bytes ?? [])];
  const cs = inetChecksum([...pseudo(src, dst, 6, seg.length), ...seg]);
  w.patch(ci, u16(cs), `${hex4(cs)} [verified]`);
  const payLen = inner?.bytes.length ?? 0;
  const summary = inner?.summary || `${t.sport} → ${t.dport} [${flagNames.join(', ')}] Seq=${t.seq >>> 0}${fl & 16 ? ` Ack=${t.ack}` : ''} Win=${t.win ?? 64240} Len=${payLen}`;
  return wrap(w, { id: 'tcp', name: 'Transmission Control Protocol', osi: 4,
    simple: `TCP carries this from port ${t.sport} to port ${t.dport} reliably. Flags [${flagNames.join(', ')}] say what this segment does; sequence ${t.seq >>> 0}${fl & 16 ? ` and acknowledgement ${t.ack}` : ''} keep every byte in order and confirmed.` },
  inner, { sport: String(t.sport), dport: String(t.dport), seq: String(t.seq >>> 0), ack: fl & 16 ? String(t.ack) : '—', flags: flagNames.join(', '), l4checksum: hex4(cs), protocol: inner?.meta.protocol ?? 'TCP' }, summary);
}

function encUdp(u: UdpSpec, inner: Enc | null, src: number[], dst: number[]): Enc {
  const w = new W();
  const len = 8 + (inner?.bytes.length ?? 0);
  w.put('Source port', u16(u.sport), String(u.sport), 'Port of the sending application.');
  w.put('Destination port', u16(u.dport), String(u.dport), 'Port of the receiving application (53 DNS, 67/68 DHCP, 123 NTP…).');
  w.put('Length', u16(len), String(len), 'Length of UDP header (8 bytes) plus data.');
  const ci = w.put('Checksum', [0, 0], '', 'Covers pseudo-header, UDP header and data. Optional in IPv4 (0 = none), mandatory in IPv6.');
  const seg = [...w.b, ...(inner?.bytes ?? [])];
  let cs = inetChecksum([...pseudo(src, dst, 17, len), ...seg]);
  if (cs === 0) cs = 0xffff;
  w.patch(ci, u16(cs), `${hex4(cs)} [verified]`);
  return wrap(w, { id: 'udp', name: 'User Datagram Protocol', osi: 4,
    simple: `UDP delivers this from port ${u.sport} to port ${u.dport}. No handshake, no acknowledgements — fast and simple, and the application handles any loss.` },
  inner, { sport: String(u.sport), dport: String(u.dport), seq: '—', ack: '—', flags: '—', l4checksum: hex4(cs), protocol: inner?.meta.protocol ?? 'UDP' }, inner?.summary || `${u.sport} → ${u.dport} Len=${len - 8}`);
}

const ICMP_NAMES: Record<string, string> = { '0/0': 'Echo Reply', '8/0': 'Echo Request', '3/0': 'Destination Unreachable (Net)', '3/1': 'Destination Unreachable (Host)', '3/3': 'Destination Unreachable (Port)', '3/4': 'Fragmentation Needed', '11/0': 'Time Exceeded (TTL expired in transit)', '5/1': 'Redirect (Host)' };
function encIcmp(c: IcmpSpec): Enc {
  const w = new W();
  const name = ICMP_NAMES[`${c.type}/${c.code}`] ?? `Type ${c.type}`;
  w.put('Type', [c.type], `${c.type} (${name.split(' (')[0]})`, 'ICMP message type: 8 Echo Request, 0 Echo Reply, 3 Destination Unreachable, 11 Time Exceeded, 5 Redirect.');
  w.put('Code', [c.code], String(c.code), 'Sub-type giving more detail (e.g. for type 3: 0 net, 1 host, 3 port unreachable).');
  const ci = w.put('Checksum', [0, 0], '', 'Covers the whole ICMP message.');
  const isEcho = c.type === 0 || c.type === 8;
  if (isEcho) {
    w.put('Identifier', u16(c.id ?? 1), hex4(c.id ?? 1), 'Identifies the ping process so replies are delivered to the right program.');
    w.put('Sequence number', u16(c.seq ?? 1), String(c.seq ?? 1), 'Increments with every echo request so lost or reordered replies can be spotted.');
    const d = ascii(c.data ?? 'abcdefghijklmnopqrstuvwabcdefghi');
    w.put('Data', d, `${d.length} bytes`, 'Arbitrary payload echoed back unchanged (Windows sends "abcdefghijklmnopqrstuvw…").');
  } else {
    w.put('Unused', [0, 0, 0, 0], '0', 'Unused for this type (or next-hop MTU for type 3 code 4).');
    if (c.inner) w.put('Original datagram', c.inner, `${c.inner.length} bytes`, 'The IP header and first 8 bytes of the packet that caused the error, so the sender can tell which flow it belongs to.');
  }
  const cs = inetChecksum(w.b);
  w.patch(ci, u16(cs), `${hex4(cs)} [verified]`);
  return wrap(w, { id: 'icmp', name: 'Internet Control Message Protocol', osi: 3, simple: isEcho
    ? (c.type === 8 ? `A ping: "Are you there?" (sequence ${c.seq ?? 1}). The target should send the same data straight back.` : `The ping reply: "Yes, I'm here!" (sequence ${c.seq ?? 1}). Timing request to reply gives the round-trip time.`)
    : `An error report: ${name}. ICMP is how routers and hosts tell a sender something went wrong.` },
  null, { protocol: 'ICMP', payload: name }, `${name}${isEcho ? ` id=${hex4(c.id ?? 1)}, seq=${c.seq ?? 1}` : ''}`);
}

function encIcmp6(c: Icmp6Spec, src: number[], dst: number[]): Enc {
  const w = new W();
  const names: Record<number, string> = { 128: 'Echo Request', 129: 'Echo Reply', 135: 'Neighbor Solicitation', 136: 'Neighbor Advertisement', 133: 'Router Solicitation', 134: 'Router Advertisement' };
  const name = names[c.type] ?? `Type ${c.type}`;
  w.put('Type', [c.type], `${c.type} (${name})`, 'ICMPv6 type. 128/129 echo; 133–137 are Neighbor Discovery (which replaces ARP in IPv6).');
  w.put('Code', [c.code], String(c.code), 'Sub-type.');
  const ci = w.put('Checksum', [0, 0], '', 'Mandatory; covers an IPv6 pseudo-header plus the message.');
  if (c.type === 128 || c.type === 129) {
    w.put('Identifier', u16(c.id ?? 1), hex4(c.id ?? 1), 'Matches replies to the requesting process.');
    w.put('Sequence', u16(c.seq ?? 1), String(c.seq ?? 1), 'Echo sequence number.');
    const d = ascii(c.data ?? 'netlab-ping-v6');
    w.put('Data', d, `${d.length} bytes`, 'Echoed payload.');
  } else if (c.type === 135 || c.type === 136) {
    w.put('Flags / reserved', c.type === 136 ? [0x60, 0, 0, 0] : [0, 0, 0, 0], c.type === 136 ? 'Solicited, Override' : '0', 'In NA: R (router), S (solicited — reply to an NS), O (override cache entry).');
    w.put('Target address', parseIPv6(c.target!), c.target!, 'The IPv6 address whose link-layer address is being resolved.');
    if (c.mac) w.put(c.type === 135 ? 'Option: Source link-layer addr' : 'Option: Target link-layer addr', [c.type === 135 ? 1 : 2, 1, ...parseMac(c.mac)], c.mac, 'The MAC address — the IPv6 equivalent of the ARP sender/target hardware address.');
  }
  const cs = inetChecksum([...pseudo(src, dst, 58, w.b.length), ...w.b]);
  w.patch(ci, u16(cs), `${hex4(cs)} [verified]`);
  return wrap(w, { id: 'icmp6', name: 'ICMPv6', osi: 3, simple: c.type === 135
    ? `IPv6 neighbor discovery: "Whoever has ${c.target}, tell me your MAC." Sent to a solicited-node multicast group rather than broadcast.`
    : c.type === 136 ? `"${c.target} is at ${c.mac}." The IPv6 replacement for an ARP reply.` : `IPv6 ping ${name.toLowerCase()} (sequence ${c.seq ?? 1}).` },
  null, { protocol: 'ICMPv6', payload: name }, `ICMPv6 ${name}${c.target ? ' for ' + c.target : ''}`);
}

// ---------------------------------------------------------------- Network
const PROTO_NAMES: Record<number, string> = { 1: 'ICMP', 6: 'TCP', 17: 'UDP', 58: 'ICMPv6' };
function encIPv4(p: IPv4Spec, proto: number, inner: Enc | null): Enc {
  const w = new W();
  const total = 20 + (inner?.bytes.length ?? 0);
  w.put('Version & IHL', [0x45], '4, 20 bytes', 'Upper 4 bits: version 4. Lower 4 bits: Internet Header Length in 32-bit words (5 × 4 = 20 bytes, no options).', 'Version=0100 (4) | IHL=0101 (5 words)');
  const tos = (p.dscp ?? 0) << 2;
  w.put('DSCP / ECN', [tos], `DSCP ${p.dscp ?? 0}, ECN 0`, 'Differentiated Services Code Point for QoS priority (e.g. 46 = Expedited Forwarding for voice), plus 2 bits of Explicit Congestion Notification.');
  w.put('Total length', u16(total), `${total} bytes`, 'Size of the entire IP packet: header plus data.');
  w.put('Identification', u16(p.id ?? 0x1c46), hex4(p.id ?? 0x1c46), 'Groups fragments of the same original datagram together.');
  const df = p.df !== false;
  w.put('Flags & fragment offset', u16(df ? 0x4000 : 0), df ? "Don't Fragment, offset 0" : 'offset 0', 'Flags: DF (don\'t fragment), MF (more fragments). Fragment offset gives this fragment\'s position in 8-byte units.', `Reserved=0 DF=${df ? 1 : 0} MF=0 | Offset=0`);
  const ttl = p.ttl ?? 64;
  w.put('Time to live', [ttl], String(ttl), 'Decremented by 1 at every router; at 0 the packet is discarded and an ICMP Time Exceeded is returned. Prevents routing loops (and powers traceroute).');
  w.put('Protocol', [proto], `${PROTO_NAMES[proto] ?? proto} (${proto})`, 'Which protocol is inside: 1 ICMP, 6 TCP, 17 UDP.');
  const ci = w.put('Header checksum', [0, 0], '', 'Covers the IP header only. Routers recompute it at every hop because TTL changes.');
  w.put('Source address', parseIPv4(p.src), p.src, 'IPv4 address of the original sender. Unchanged end-to-end (unless NAT rewrites it).');
  w.put('Destination address', parseIPv4(p.dst), p.dst, 'IPv4 address of the final destination. Routers use it to choose the next hop.');
  const cs = inetChecksum(w.b);
  w.patch(ci, u16(cs), `${hex4(cs)} [verified]`);
  return wrap(w, { id: 'ipv4', name: 'Internet Protocol Version 4', osi: 3,
    simple: `IP is the addressing on the envelope: from ${p.src} to ${p.dst}. Routers read the destination to forward it. TTL ${ttl} means it may cross at most ${ttl} more routers.` },
  inner, { srcIp: p.src, dstIp: p.dst, ttl: String(ttl), ipChecksum: hex4(cs), protocol: inner?.meta.protocol ?? PROTO_NAMES[proto] }, inner?.summary);
}

function encIPv6(p: IPv6Spec, next: number, inner: Enc | null): Enc {
  const w = new W();
  const plen = inner?.bytes.length ?? 0;
  const flow = p.flow ?? 0;
  w.put('Version, traffic class, flow label', u32((6 << 28) | flow), `6, TC 0, flow ${hex4(flow)}`, 'Version 6 (4 bits), Traffic Class for QoS (8 bits), and a 20-bit Flow Label to identify packets of the same flow.', `Version=0110 | TC=00000000 | Flow=${flow.toString(2).padStart(20, '0')}`);
  w.put('Payload length', u16(plen), `${plen} bytes`, 'Length of everything after the fixed 40-byte header.');
  w.put('Next header', [next], `${PROTO_NAMES[next] ?? next} (${next})`, 'Type of the next header — a transport protocol or an extension header. Same numbering as IPv4 Protocol.');
  const hop = p.hop ?? 64;
  w.put('Hop limit', [hop], String(hop), 'Same role as IPv4 TTL: decremented at each router. There is no header checksum in IPv6, so routers do less work.');
  w.put('Source address', parseIPv6(p.src), fmtIPv6(parseIPv6(p.src)), '128-bit source address.');
  w.put('Destination address', parseIPv6(p.dst), fmtIPv6(parseIPv6(p.dst)), '128-bit destination address. ff02::… addresses are link-local multicast.');
  return wrap(w, { id: 'ipv6', name: 'Internet Protocol Version 6', osi: 3,
    simple: `IPv6 addressing: from ${p.src} to ${p.dst}. The header is a fixed 40 bytes with no checksum — simpler and faster for routers.` },
  inner, { srcIp: fmtIPv6(parseIPv6(p.src)), dstIp: fmtIPv6(parseIPv6(p.dst)), ttl: `${hop} (hop limit)`, ipChecksum: 'none (IPv6)', protocol: inner?.meta.protocol ?? PROTO_NAMES[next] }, inner?.summary);
}

function encArp(a: ArpSpec): Enc {
  const w = new W();
  w.put('Hardware type', u16(1), 'Ethernet (1)', 'Type of link-layer network.');
  w.put('Protocol type', u16(0x0800), 'IPv4 (0x0800)', 'Which network-layer address is being resolved.');
  w.put('Hardware size', [6], '6', 'MAC address length.');
  w.put('Protocol size', [4], '4', 'IPv4 address length.');
  w.put('Opcode', u16(a.op), a.op === 1 ? 'request (1)' : 'reply (2)', '1 = request ("who has?"), 2 = reply ("is at").');
  w.put('Sender MAC', parseMac(a.sha), a.sha, 'MAC of the sender. Receivers learn (cache) this mapping.');
  w.put('Sender IP', parseIPv4(a.spa), a.spa, 'IPv4 address of the sender.');
  w.put('Target MAC', parseMac(a.tha), a.tha, a.op === 1 ? 'Unknown yet — all zeros in a request.' : 'MAC of the original requester.');
  w.put('Target IP', parseIPv4(a.tpa), a.tpa, 'The IPv4 address being resolved.');
  const summary = a.op === 1 ? `Who has ${a.tpa}? Tell ${a.spa}` : `${a.spa} is at ${a.sha}`;
  return wrap(w, { id: 'arp', name: 'Address Resolution Protocol', osi: 2.5,
    simple: a.op === 1 ? `ARP request to everyone on the LAN: "Who has ${a.tpa}? Tell ${a.spa}." The sender knows the IP but needs the MAC to build an Ethernet frame.` : `ARP reply: "${a.spa} is at ${a.sha}." The requester stores this in its ARP cache.` },
  null, { srcIp: a.spa, dstIp: a.tpa, protocol: 'ARP', payload: summary, ttl: '—', sport: '—', dport: '—', seq: '—', ack: '—', flags: '—' }, summary);
}

function encEth(e: EthSpec, type: number, inner: Enc | null): Enc {
  const w = new W();
  const dst = parseMac(e.dst);
  const bcast = dst.every((b) => b === 255);
  const mcast = !bcast && (dst[0] & 1) === 1;
  w.put('Destination MAC', dst, fmtMac(dst) + (bcast ? ' (broadcast)' : mcast ? ' (multicast)' : ''), 'Link-layer address of the next device on THIS link (not necessarily the final destination). ff:ff:ff:ff:ff:ff reaches every device on the LAN.');
  w.put('Source MAC', parseMac(e.src), e.src, 'Burned-in hardware address of the sending interface. Switches learn which port each source MAC lives on.');
  (e.vlan ?? []).forEach((vid, i) => {
    w.put(`802.1Q tag ${i + 1}`, [0x81, 0x00, ...u16(vid & 0x0fff)], `VLAN ${vid}`, 'TPID 0x8100 followed by priority (3 bits), DEI (1 bit) and VLAN ID (12 bits). Tags tell trunk links which VLAN a frame belongs to.', `TPID=0x8100 | PCP=0 DEI=0 | VID=${vid}`);
  });
  const typeName: Record<number, string> = { 0x0800: 'IPv4', 0x86dd: 'IPv6', 0x0806: 'ARP' };
  w.put('EtherType', u16(type), `${typeName[type] ?? ''} (${hex4(type)})`, 'Identifies the payload protocol: 0x0800 IPv4, 0x86DD IPv6, 0x0806 ARP, 0x8100 VLAN tag.');
  const mt = { srcMac: e.src, dstMac: fmtMac(dst) };
  return wrap(w, { id: 'eth', name: e.vlan?.length ? 'Ethernet II + 802.1Q' : 'Ethernet II', osi: 2,
    simple: `The Ethernet frame is the local delivery label: from MAC ${e.src} to ${bcast ? 'EVERY device (broadcast)' : fmtMac(dst)}. It is rewritten at every router hop.` },
  inner, mt, inner?.summary);
}

// ---------------------------------------------------------------- Compose
const cache = new Map<string, Packet>();
export function buildPacket(spec: PacketSpec): Packet {
  const key = JSON.stringify(spec);
  const hit = cache.get(key);
  if (hit) return hit;
  let enc: Enc | null = null;
  const a = spec.app;
  if (a) {
    enc = a.kind === 'dns' ? encDns(a.dns) : a.kind === 'dhcp' ? encDhcp(a.dhcp) : a.kind === 'http' ? encHttp(a.text) : a.kind === 'tls' ? encTls(a.records) : encRaw(a.text, a.name);
  }
  const src = spec.ipv4 ? parseIPv4(spec.ipv4.src) : spec.ipv6 ? parseIPv6(spec.ipv6.src) : [];
  const dst = spec.ipv4 ? parseIPv4(spec.ipv4.dst) : spec.ipv6 ? parseIPv6(spec.ipv6.dst) : [];
  let proto = 0;
  if (spec.tcp) { enc = encTcp(spec.tcp, enc, src, dst); proto = 6; }
  else if (spec.udp) { enc = encUdp(spec.udp, enc, src, dst); proto = 17; }
  else if (spec.icmp) { enc = encIcmp(spec.icmp); proto = 1; }
  else if (spec.icmp6) { enc = encIcmp6(spec.icmp6, src, dst); proto = 58; }
  let type = 0x0800;
  if (spec.ipv4) enc = encIPv4(spec.ipv4, proto, enc);
  else if (spec.ipv6) { enc = encIPv6(spec.ipv6, proto, enc); type = 0x86dd; }
  else if (spec.arp) { enc = encArp(spec.arp); type = 0x0806; }
  if (spec.eth) enc = encEth(spec.eth, type, enc);
  if (!enc) throw new Error('Empty packet spec');
  const pkt: Packet = {
    bytes: enc.bytes,
    layers: enc.layers,
    meta: { ...enc.meta, length: `${enc.bytes.length} bytes on wire (excl. FCS)` },
    summary: enc.summary,
  };
  cache.set(key, pkt);
  return pkt;
}

export function fieldAt(p: Packet, offset: number): { layer: Layer; field: Field } | null {
  for (const l of p.layers) for (const f of l.fields) if (offset >= f.start && offset < f.start + f.len) return { layer: l, field: f };
  return null;
}
export { hex2 };
